import React from 'react';
import { motion } from 'framer-motion';
import { X } from 'lucide-react';
import Link from 'next/link';
import { ProjectData } from './PolaroidCard';

interface ExpandedPolaroidProps {
  project: ProjectData;
  onClose: () => void;
}

export default function ExpandedPolaroid({ project, onClose }: ExpandedPolaroidProps) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center pointer-events-none">
      
      {/* Backdrop Blur */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
        className="absolute inset-0 bg-white/40 backdrop-blur-sm pointer-events-auto"
      />

      {/* Expanded Card Container */}
      <div className="relative w-full max-w-[450px] pointer-events-auto px-4 z-10">
        <motion.div
          layoutId={`polaroid-container-${project.id}`}
          className="w-full bg-[#fdfdfc] p-6 shadow-2xl border border-gray-200 rounded-sm flex flex-col relative"
          // Slight paper texture for the expanded view
          style={{ 
            backgroundImage: "url(data:image/png;base64,)",
            backgroundSize: "120px"
          }}
        >
          {/* Close Button */}
          <button 
            onClick={onClose}
            className="absolute top-4 right-4 z-20 text-gray-500 hover:text-black transition-colors bg-white/50 rounded-full p-1"
          >
            <X size={24} />
          </button>

          {/* Image */}
          <motion.div 
            layoutId={`polaroid-image-${project.id}`}
            className="w-full aspect-[4/3] bg-gray-200 mb-6 border border-gray-100 shadow-inner" 
          />
          
          {/* Title */}
          <motion.h3 
            layoutId={`polaroid-title-${project.id}`}
            className="text-3xl text-center text-black font-bold mb-4 border-b-2 border-dashed border-gray-300 pb-2"
          >
            {project.title}
          </motion.h3>

          {/* Description */}
          <motion.p 
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="text-xl text-gray-700 leading-relaxed mb-8 flex-grow"
          >
            {project.description}
          </motion.p>

          {/* Action Button */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
          >
            <Link 
              href={project.link}
              className="block w-full py-3 text-center bg-black text-white rounded-sm text-2xl font-bold hover:bg-gray-800 transition-colors shadow-md"
            >
              View Full Project
            </Link>
          </motion.div>

        </motion.div>
      </div>
    </div>
  );
}